CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_fee_payment_batch()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_batch UUID;
BEGIN

    SELECT batch_id
    INTO v_batch
    FROM public.students
    WHERE id = NEW.student_id;


    IF v_batch IS NULL THEN

        RAISE EXCEPTION
        'Student % not found or student has no batch',
        NEW.student_id;

    END IF;


    NEW.batch_id := v_batch;

    RETURN NEW;

END
$function$

CREATE OR REPLACE FUNCTION public.portal_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at := NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_initialize_fee_month(p_payment_month text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_result TEXT;
BEGIN

    IF NOT public.is_portal_admin() THEN
        RAISE EXCEPTION
            'Administrator access required'
            USING ERRCODE = '42501';
    END IF;


    SELECT
        public.initialize_fee_month(
            p_payment_month
        )::TEXT
    INTO v_result;


    RETURN COALESCE(
        NULLIF(v_result, '')::INTEGER,
        0
    );

END;
$function$

