CREATE OR REPLACE FUNCTION public.update_student_basic(p_student_id uuid, p_name text, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_name TEXT;
    v_status TEXT;
    v_updated INTEGER;
BEGIN

    v_name := trim(COALESCE(p_name, ''));
    v_status := lower(trim(COALESCE(p_status, 'enrolled')));

    IF v_name = '' THEN
        RAISE EXCEPTION 'Student name cannot be empty';
    END IF;

    IF v_status NOT IN ('enrolled', 'trial') THEN
        RAISE EXCEPTION 'Invalid student status: %', v_status;
    END IF;

    UPDATE public.students
    SET
        name = v_name,
        status = v_status
    WHERE id = p_student_id;

    GET DIAGNOSTICS v_updated = ROW_COUNT;

    IF v_updated = 0 THEN
        RAISE EXCEPTION 'Student not found: %', p_student_id;
    END IF;

END;
$function$

CREATE OR REPLACE FUNCTION public.update_student_details(p_student_id uuid, p_name text, p_status text, p_stream text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_name TEXT;

    v_status TEXT;

    v_updated INTEGER;
BEGIN

    v_name :=
        trim(
            COALESCE(
                p_name,
                ''
            )
        );


    v_status :=
        lower(
            trim(
                COALESCE(
                    p_status,
                    'enrolled'
                )
            )
        );


    IF v_name = '' THEN
        RAISE EXCEPTION
            'Student name cannot be empty.';
    END IF;


    IF v_status NOT IN (
        'enrolled',
        'trial'
    ) THEN
        RAISE EXCEPTION
            'Invalid student status: %',
            v_status;
    END IF;


    IF p_stream IS NULL
       OR cardinality(p_stream) < 1
    THEN
        RAISE EXCEPTION
            'At least one subject must be selected.';
    END IF;


    UPDATE public.students

    SET
        name = v_name,
        status = v_status,
        stream = p_stream

    WHERE id = p_student_id;


    GET DIAGNOSTICS
        v_updated = ROW_COUNT;


    IF v_updated = 0 THEN
        RAISE EXCEPTION
            'Student not found: %',
            p_student_id;
    END IF;

END;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_student_fee_remarks(p_student_id uuid, p_remarks text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_remarks TEXT;
BEGIN
    IF NOT public.is_portal_admin() THEN
        RAISE EXCEPTION
            'Administrator access required'
            USING ERRCODE = '42501';
    END IF;

    IF p_student_id IS NULL THEN
        RAISE EXCEPTION 'Student id is required';
    END IF;

    v_remarks := NULLIF(
        TRIM(COALESCE(p_remarks, '')),
        ''
    );

    IF v_remarks IS NOT NULL
       AND CHAR_LENGTH(v_remarks) > 500
    THEN
        RAISE EXCEPTION
            'Fee remarks cannot exceed 500 characters';
    END IF;

    UPDATE public.students
    SET fee_remarks = v_remarks
    WHERE id = p_student_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Student not found: %',
            p_student_id;
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_award_mark()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_batch_id UUID;
    v_subject_code TEXT;
    v_max_marks NUMERIC;
    v_valid_student BOOLEAN;
BEGIN

    SELECT
        t.batch_id,
        t.subject_code,
        t.max_marks
    INTO
        v_batch_id,
        v_subject_code,
        v_max_marks
    FROM public.award_tests t
    WHERE t.id = NEW.test_id;


    IF v_batch_id IS NULL THEN
        RAISE EXCEPTION
            'Award test does not exist.';
    END IF;


    -- ========================================================
    -- ABSENT
    -- ========================================================

    IF COALESCE(
        NEW.is_absent,
        FALSE
    ) THEN

        NEW.is_absent := TRUE;
        NEW.marks := NULL;

    ELSE

        NEW.is_absent := FALSE;

        IF NEW.marks IS NULL THEN
            RAISE EXCEPTION
                'Marks are required unless student is absent.';
        END IF;


        IF NEW.marks < 0
           OR NEW.marks > v_max_marks
        THEN

            RAISE EXCEPTION
                'Marks must be between 0 and %.',
                v_max_marks;

        END IF;

    END IF;


    -- ========================================================
    -- STUDENT MUST BELONG TO BATCH + SUBJECT
    -- ========================================================

    SELECT EXISTS (
        SELECT 1
        FROM public.students s
        WHERE s.id = NEW.student_id
          AND s.batch_id = v_batch_id
          AND v_subject_code = ANY(
              COALESCE(
                  s.stream,
                  ARRAY[]::TEXT[]
              )
          )
    )
    INTO v_valid_student;


    IF NOT v_valid_student THEN
        RAISE EXCEPTION
            'Student does not belong to this batch/subject.';
    END IF;


    NEW.updated_at := NOW();

    RETURN NEW;

END;
$function$

CREATE OR REPLACE FUNCTION public.save_award_marks(p_test_id uuid, p_marks jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_item JSONB;

    v_student_id UUID;

    v_marks NUMERIC;

    v_is_absent BOOLEAN;

    v_count INTEGER := 0;
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Authentication required.'
            USING ERRCODE = '42501';
    END IF;


    IF NOT public.can_manage_award_test(
        p_test_id
    ) THEN

        RAISE EXCEPTION
            'You are not allowed to edit this award list.'
            USING ERRCODE = '42501';

    END IF;


    IF p_marks IS NULL
       OR jsonb_typeof(p_marks) <> 'array'
    THEN

        RAISE EXCEPTION
            'Marks payload must be a JSON array.';

    END IF;


    FOR v_item IN
        SELECT value
        FROM jsonb_array_elements(
            p_marks
        )
    LOOP

        v_student_id :=
            (v_item ->> 'student_id')::UUID;


        v_is_absent :=
            COALESCE(
                (
                    v_item
                    ->>
                    'is_absent'
                )::BOOLEAN,
                FALSE
            );


        IF v_is_absent THEN

            v_marks := NULL;

        ELSE

            IF NOT (
                v_item ? 'marks'
            )
            OR v_item -> 'marks'
               = 'null'::JSONB
            THEN

                RAISE EXCEPTION
                    'Marks are required unless student is absent.';

            END IF;


            v_marks :=
                (
                    v_item
                    ->>
                    'marks'
                )::NUMERIC;

        END IF;


        INSERT INTO public.award_marks (
            test_id,
            student_id,
            marks,
            is_absent,
            updated_by,
            updated_at
        )
        VALUES (
            p_test_id,
            v_student_id,
            CASE
                WHEN v_is_absent
                    THEN NULL
                ELSE ROUND(
                    v_marks,
                    2
                )
            END,
            v_is_absent,
            auth.uid(),
            NOW()
        )

        ON CONFLICT (
            test_id,
            student_id
        )

        DO UPDATE SET
            marks =
                EXCLUDED.marks,
            is_absent =
                EXCLUDED.is_absent,
            updated_by =
                auth.uid(),
            updated_at =
                NOW();


        v_count :=
            v_count + 1;

    END LOOP;


    RETURN v_count;

END;
$function$

CREATE OR REPLACE FUNCTION public.create_award_test(p_batch_id uuid, p_subject_code text, p_test_date date, p_max_marks numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_class_level SMALLINT;
    v_next_test_no INTEGER;
    v_test_id UUID;
    v_student_count INTEGER;
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Authentication required.'
            USING ERRCODE = '42501';
    END IF;


    IF p_subject_code NOT IN (
        'Phy',
        'Chem',
        'Math',
        'Eng',
        'Comp',
        'Bio'
    ) THEN
        RAISE EXCEPTION
            'Invalid subject.';
    END IF;


    IF p_test_date IS NULL THEN
        RAISE EXCEPTION
            'Test date is required.';
    END IF;


    IF p_test_date > CURRENT_DATE THEN
        RAISE EXCEPTION
            'Test date cannot be in the future.';
    END IF;


    IF p_max_marks IS NULL
       OR p_max_marks <= 0 THEN

        RAISE EXCEPTION
            'Maximum marks must be greater than zero.';

    END IF;


    SELECT b.class_level
    INTO v_class_level
    FROM public.batches b
    WHERE b.id = p_batch_id;


    IF v_class_level IS NULL THEN
        RAISE EXCEPTION
            'Batch not found.';
    END IF;


    IF NOT (
        public.is_portal_admin()

        OR public.can_manage_award_subject(
            v_class_level,
            p_subject_code
        )
    ) THEN

        RAISE EXCEPTION
            'You are not assigned to this subject/class.'
            USING ERRCODE = '42501';

    END IF;


    -- At least one student must study this subject.
    -- Attendance is intentionally not involved.

    SELECT COUNT(*)
    INTO v_student_count

    FROM public.students s

    WHERE s.batch_id = p_batch_id

    AND p_subject_code = ANY(
        COALESCE(
            s.stream,
            ARRAY[]::TEXT[]
        )
    );


    IF v_student_count = 0 THEN

        RAISE EXCEPTION
            'No students were found for this batch and subject.';

    END IF;


    -- Prevent duplicate T-number generation.

    PERFORM pg_advisory_xact_lock(
        hashtext(
            p_batch_id::TEXT
            || ':'
            || p_subject_code
        )
    );


    SELECT
        COALESCE(
            MAX(t.test_no),
            0
        ) + 1

    INTO v_next_test_no

    FROM public.award_tests t

    WHERE t.batch_id = p_batch_id

    AND t.subject_code = p_subject_code;


    INSERT INTO public.award_tests (
        batch_id,
        subject_code,
        test_no,
        test_date,
        max_marks,
        created_by
    )
    VALUES (
        p_batch_id,
        p_subject_code,
        v_next_test_no,
        p_test_date,
        ROUND(p_max_marks, 2),
        auth.uid()
    )
    RETURNING id
    INTO v_test_id;


    RETURN v_test_id;

END;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_portal_user_active(p_user_id uuid, p_active boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN

    IF NOT public.is_portal_admin() THEN
        RAISE EXCEPTION
            'Administrator access required'
            USING ERRCODE = '42501';
    END IF;


    IF p_user_id IS NULL THEN
        RAISE EXCEPTION
            'User id is required.';
    END IF;


    IF p_active IS NULL THEN
        RAISE EXCEPTION
            'Active status is required.';
    END IF;


    IF p_user_id = auth.uid()
       AND p_active = FALSE
    THEN
        RAISE EXCEPTION
            'You cannot disable your own account.';
    END IF;


    UPDATE public.user_profiles
    SET
        is_active = p_active,
        updated_at = NOW()
    WHERE user_id = p_user_id;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Portal user not found.';
    END IF;

END;
$function$

CREATE OR REPLACE FUNCTION private.capture_teacher_registration_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
DECLARE
    v_name TEXT;
    v_email TEXT;
    v_subject TEXT;
    v_levels SMALLINT[];
BEGIN

    -- Normal Auth users should not create teacher requests.
    IF COALESCE(
        NEW.raw_user_meta_data
            ->> 'portal_registration',
        ''
    ) <> 'teacher_request'
    THEN
        RETURN NEW;
    END IF;


    v_name :=
        btrim(
            COALESCE(
                NEW.raw_user_meta_data
                    ->> 'full_name',
                ''
            )
        );

    v_email :=
        lower(
            btrim(
                COALESCE(
                    NEW.email,
                    ''
                )
            )
        );

    v_subject :=
        btrim(
            COALESCE(
                NEW.raw_user_meta_data
                    ->> 'subject_name',
                ''
            )
        );


    SELECT
        COALESCE(
            ARRAY_AGG(
                DISTINCT parsed.level_value
                ORDER BY parsed.level_value
            ),
            ARRAY[]::SMALLINT[]
        )
    INTO v_levels
    FROM (
        SELECT
            value::SMALLINT
                AS level_value
        FROM jsonb_array_elements_text(
            COALESCE(
                NEW.raw_user_meta_data
                    -> 'class_levels',
                '[]'::JSONB
            )
        ) AS item(value)
        WHERE value IN (
            '9',
            '10',
            '11',
            '12'
        )
    ) AS parsed;


    IF char_length(v_name)
       NOT BETWEEN 2 AND 100
    THEN
        RAISE EXCEPTION
            'Valid teacher name is required.';
    END IF;


    IF v_email = '' THEN
        RAISE EXCEPTION
            'Teacher email is required.';
    END IF;


    IF char_length(v_subject)
       NOT BETWEEN 1 AND 80
    THEN
        RAISE EXCEPTION
            'Valid teacher subject is required.';
    END IF;


    IF cardinality(v_levels) = 0 THEN
        RAISE EXCEPTION
            'At least one class is required.';
    END IF;


    -- Do not allow an already-active portal account
    -- to create another teacher request.

    IF EXISTS (
        SELECT 1
        FROM public.user_profiles p
        WHERE lower(p.email) = v_email
    ) THEN
        RAISE EXCEPTION
            'A portal account already exists for this email.';
    END IF;


    INSERT INTO public.teacher_registration_requests (
        auth_user_id,
        full_name,
        email,
        subject_name,
        class_levels,
        status
    )
    VALUES (
        NEW.id,
        v_name,
        v_email,
        v_subject,
        v_levels,
        'pending'
    );


    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_fee_teacher_name(p_level_group text, p_subject_code text, p_teacher_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_group TEXT;
    v_subject TEXT;
    v_name TEXT;
BEGIN
    IF NOT public.is_portal_admin() THEN
        RAISE EXCEPTION
            'Administrator access required'
            USING ERRCODE = '42501';
    END IF;

    v_group := UPPER(TRIM(COALESCE(p_level_group, '')));
    v_subject := TRIM(COALESCE(p_subject_code, ''));
    v_name := TRIM(COALESCE(p_teacher_name, ''));

    IF v_group NOT IN ('SSC', 'HSSC') THEN
        RAISE EXCEPTION 'Invalid level group';
    END IF;

    IF v_subject = '' THEN
        RAISE EXCEPTION 'Subject is required';
    END IF;

    IF v_name = '' THEN
        RAISE EXCEPTION 'Teacher name is required';
    END IF;

    IF CHAR_LENGTH(v_name) > 120 THEN
        RAISE EXCEPTION 'Teacher name is too long';
    END IF;

    UPDATE public.fee_teacher_assignments
    SET teacher_name = v_name
    WHERE level_group = v_group
      AND subject_code = v_subject;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Fee teacher assignment not found: % / %',
            v_group,
            v_subject;
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_fee_month_teacher_name(p_payment_month text, p_level_group text, p_subject_code text, p_teacher_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_month TEXT;
    v_group TEXT;
    v_subject TEXT;
    v_name TEXT;
BEGIN
    IF NOT public.is_portal_admin() THEN
        RAISE EXCEPTION
            'Administrator access required'
            USING ERRCODE = '42501';
    END IF;

    v_month := TRIM(COALESCE(p_payment_month, ''));
    v_group := UPPER(TRIM(COALESCE(p_level_group, '')));
    v_subject := TRIM(COALESCE(p_subject_code, ''));
    v_name := TRIM(COALESCE(p_teacher_name, ''));

    IF v_month = '' THEN
        RAISE EXCEPTION 'Payment month is required';
    END IF;

    IF v_group NOT IN ('SSC', 'HSSC') THEN
        RAISE EXCEPTION 'Invalid level group';
    END IF;

    IF v_subject = '' THEN
        RAISE EXCEPTION 'Subject is required';
    END IF;

    IF v_name = '' THEN
        RAISE EXCEPTION 'Teacher name is required';
    END IF;

    UPDATE public.fee_month_teacher_assignments
    SET
        teacher_name = v_name,
        updated_at = NOW(),
        updated_by = auth.uid()
    WHERE payment_month = v_month
      AND level_group = v_group
      AND subject_code = v_subject;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Teacher assignment not found';
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_award_test(p_test_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_created_by UUID;
    v_role TEXT;
    v_is_active BOOLEAN;
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION
            'Authentication required.'
            USING ERRCODE = '42501';
    END IF;


    SELECT
        created_by
    INTO
        v_created_by
    FROM public.award_tests
    WHERE id = p_test_id;


    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Award test does not exist.';
    END IF;


    SELECT
        role,
        is_active
    INTO
        v_role,
        v_is_active
    FROM public.user_profiles
    WHERE user_id = auth.uid();


    IF COALESCE(v_is_active, FALSE) = FALSE THEN
        RAISE EXCEPTION
            'Portal account is inactive.'
            USING ERRCODE = '42501';
    END IF;


    IF v_role <> 'admin'
       AND v_created_by <> auth.uid()
    THEN
        RAISE EXCEPTION
            'You can only delete award tests created by you.'
            USING ERRCODE = '42501';
    END IF;


    DELETE FROM public.award_marks
    WHERE test_id = p_test_id;


    DELETE FROM public.award_tests
    WHERE id = p_test_id;


    RETURN TRUE;

END;
$function$
